function requireMRXUI(admin=false){if(!mrxUI())throw Error('Research missions are unavailable.');if(admin)requireAdmin();if(mrxBusy)throw Error('Wait for the current research action.');}
async function mrxRun(work){requireMRXUI();const a=actor.id,e=mrxEpoch;mrxBusy=true;mrxError='';render();try{const result=await work();if(actor?.id!==a||e!==mrxEpoch||!mrxUI())throw Error('Research access changed. Reopen the intended workspace.');return result;}catch(error){if(actor?.id===a&&e===mrxEpoch)mrxError=error.message;throw error;}finally{if(actor?.id===a&&e===mrxEpoch){mrxBusy=false;render();}}}
